import React, { useState, useEffect, useRef } from 'react';
import './MediaRenderer.css';

const MediaRenderer = ({ mediaUrl, mediaType, fileName, onLoadError }) => {
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState(null);
    const [showFullscreen, setShowFullscreen] = useState(false);
    const [isPlaying, setIsPlaying] = useState(false);
    const videoRef = useRef(null);
    const audioRef = useRef(null);

    useEffect(() => {
        setIsLoading(true);
        setError(null);
    }, [mediaUrl]);

    const handleLoad = () => {
        setIsLoading(false);
    };

    const handleError = (e) => {
        setIsLoading(false);
        setError('Не удалось загрузить медиа');
        onLoadError?.();
        console.error('Media load error:', e);
    };

    const toggleFullscreen = () => {
        setShowFullscreen(!showFullscreen);
    };

    const handlePlayPause = () => {
        if (videoRef.current) {
            if (isPlaying) {
                videoRef.current.pause();
            } else {
                videoRef.current.play();
            }
            setIsPlaying(!isPlaying);
        }
    };

    const renderImage = () => (
        <div className="media-image-container">
            {isLoading && (
                <div className="media-loading">
                    <div className="spinner"></div>
                </div>
            )}
            <img
                src={mediaUrl}
                alt={fileName || 'Изображение'}
                className={`media-image ${isLoading ? 'hidden' : ''}`}
                onLoad={handleLoad}
                onError={handleError}
                onClick={toggleFullscreen}
                loading="lazy"
            />
            {showFullscreen && (
                <div className="media-fullscreen" onClick={toggleFullscreen}>
                    <img src={mediaUrl} alt={fileName} />
                </div>
            )}
        </div>
    );

    const renderVideo = () => (
        <div className="media-video-container">
            {isLoading && (
                <div className="media-loading">
                    <div className="spinner"></div>
                </div>
            )}
            <video
                ref={videoRef}
                src={mediaUrl}
                className={`media-video ${isLoading ? 'hidden' : ''}`}
                controls={!isLoading}
                onLoadedData={handleLoad}
                onError={handleError}
                onPlay={() => setIsPlaying(true)}
                onPause={() => setIsPlaying(false)}
                preload="metadata"
            />
            {error && <div className="media-error">{error}</div>}
        </div>
    );

    const renderAudio = () => (
        <div className="media-audio-container">
            <audio
                ref={audioRef}
                src={mediaUrl}
                controls
                className="media-audio"
                onLoadedData={handleLoad}
                onError={handleError}
                preload="metadata"
            />
            {error && <div className="media-error">{error}</div>}
        </div>
    );

    if (error) {
        return (
            <div className="media-error-container">
                <span className="media-error-icon">⚠️</span>
                <span className="media-error-text">{error}</span>
            </div>
        );
    }

    switch (mediaType) {
        case 'image':
            return renderImage();
        case 'video':
            return renderVideo();
        case 'audio':
            return renderAudio();
        default:
            return (
                <div className="media-unknown">
                    <a href={mediaUrl} target="_blank" rel="noopener noreferrer">
                        📎 {fileName || 'Скачать файл'}
                    </a>
                </div>
            );
    }
};

export default MediaRenderer;
